message.content:
{
  "gate_token": "sJ_L4vENW61XANefNc5v6Q",
  "title": "The Mirror Road Through the Ruined City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls the rescue map at the broken city wall.",
      "visual_description": "A cracked stone wall at dusk; an ink-stained coated figure spreads a hand-drawn map across rubble, brass compass glinting beside her.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious temptations ahead.",
      "visual_description": "A small oil lamp held aloft, its single flame-eye narrowed; behind it, silhouettes of distant towers and tattered royal banners.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts ahead through the rubble.",
      "visual_description": "A clockwork fox with a slowly winding key-tail picks across shattered cobblestones, blue glass eyes catching torchlight.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver slips out of a cracked window into the street.",
      "visual_description": "A figure in a clear diving helmet emerges from a tall warped windowpane as if from water, coat reflecting fragments of the ruined skyline.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The party meets at the looming castle gates.",
      "visual_description": "Massive iron gates hung with faded royal banners; four figures gather in their long shadow under a bruised sky.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "They find the sleeping tax collector slumped at the gatehouse.",
      "visual_description": "An official snoring on a thick ledger book, stamped papers stuck to his sleeves, an overturned inkpot pooling near his boot.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Mara avoids the cursed tower despite the lure.",
      "visual_description": "A leaning spire wreathed in violet mist beckons from across a courtyard; Mara turns her shoulder against it, tugging the lamp away.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "Tin Fox spies an armored patrol on the avenue.",
      "visual_description": "From behind a toppled statue, the metal fox peers at marching steel-clad figures whose faces are hidden by visors and banner-shadow.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Glass Diver hides the team inside a shop mirror.",
      "visual_description": "A tall cracked mirror in an abandoned tailor's shop; four travelers ripple into its silver surface as the diver holds the frame steady.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Frightened townspeople whisper of a winged beast in the clouds.",
      "visual_description": "Hooded townspeople clustered in a doorway, pointing up at a long serpentine shadow gliding above the ruined rooftops.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The lamp insists the rumored beast is only a distraction.",
      "visual_description": "Close-up on the lamp's flame-eye, blazing brighter; in its reflection, the winged shape dissolves into mere smoke and banners.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "They reach a sealed magic door in the throne wing.",
      "visual_description": "An arched door etched with luminous runes pulses softly in a corridor lined with cobwebbed portraits and ripped tapestries.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox picks the rune-lock with a turning key-tail.",
      "visual_description": "The clockwork fox crouched against the door, its key-tail rotating into a glowing rune; sparks of pale gold drift upward.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "Glass Diver dives through a stained window to reach the captive.",
      "visual_description": "A vast stained-glass scene of an old royal hunt; the diver plunges into it headfirst, light shattering around the helmet.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Inside the chamber, Mara finds the sleeping tax collector again, somehow.",
      "visual_description": "A dim chamber with a slumped official across the rescue route, ledger pages fluttering as Mara stares in disbelief, lamp glowering.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "They haul the dozing official out as alarms ring.",
      "visual_description": "Mara and the diver drag the snoring tax collector by the ankles down a torchlit staircase, stamped papers trailing like a paper comet.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The team sprints onto the long bridge as patrols close in.",
      "visual_description": "A narrow stone bridge over a black river; four rescuers and one snoring bundle race across as armored shapes mass at the far gatehouse behind.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "On the far bank, Mara folds the map; the lamp finally smiles.",
      "visual_description": "Dawn over the river; the ruined city glimmers behind them, the tax collector still asleep on the grass, the fox curled on the map, lamp's eye softened to a warm crescent.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

